package com.bananalab.lite;
import android.content.*;import org.json.*;import java.util.*;import java.util.regex.*;
/** Local intent adapter. Complete bounded requests only; never invents an arbitrary Java patch. */
final class NaturalCoding{
 static final class Plan{String kind="",command="",target="",detail="";Plan(){}Plan(String k,String c,String t){kind=k;command=c;target=t;}}
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-natural-coding",0);}
 static String polite(String raw){return raw.trim().replaceFirst("(?iu)^(?:banana[, ]+)?(?:(?:por favor[, ]+)?(?:podes|podrias|puedes|podrías|podés)\\s+|(?:quiero|necesito|me gustaria)\\s+que\\s+)?","").replaceFirst("(?iu)[, ]+por favor[.! ]*$","").trim();}
 static String normalize(String raw){String q=ChatLanguage.normalize(polite(raw)).replaceFirst("^(?:cambiame|cambiale|cambiarme|modificame|pinta|pintame) ","cambia ").replaceFirst("^(?:poneme|ponele|pon|ponle) ","pone ");return q.replaceFirst("^me gustaria que ","").replaceFirst("^quiero ","").replaceFirst("^necesito ","");}
 static String setting(String clause){String typography=UiTypeface.command(clause);if(typography!=null)return typography;String q=normalize(clause);q=q.replaceFirst("^(?:cambies|modifiques|pongas|hagas|agrandes|aumentes|reduzcas|achiques|uses|crees|agregues|quites)\\b",q.startsWith("cambies")?"cambia":q.startsWith("modifiques")?"cambia":q.startsWith("pongas")?"pone":q.startsWith("hagas")?"hace":q.startsWith("agrandes")?"agranda":q.startsWith("aumentes")?"aumenta":q.startsWith("reduzcas")?"reduce":q.startsWith("achiques")?"achica":q.startsWith("uses")?"usa":q.startsWith("crees")?"crea":q.startsWith("agregues")?"agrega":"quita");
  q=q.replaceFirst("^los botones(?: de la app)? (?:sean|sean de color|sean color) ","pone los botones ").replaceFirst("^(?:la letra|el texto)(?: del chat)? sea mas ","hace el texto del chat mas ");
  Matcher desired=Pattern.compile("(?:que )?(?:el )?boton ([a-z0-9 ]+?) (?:sea|quede|se vea) (?:de color )?(rojo|azul|verde|violeta|amarillo|original)").matcher(q);if(desired.matches())return "pone el boton "+desired.group(1).trim()+" "+desired.group(2);
  Matcher size=Pattern.compile("(?:cambia|pone|ajusta|establece) (?:(?:el|la) )?(?:tamano de (?:la letra|el texto)|tamano del texto|texto|letra)(?: del chat| de la app)? (?:a|en) ([0-9]+)(?: sp| puntos)?").matcher(q);if(size.matches())return "pone el texto del chat a "+size.group(1);
  Matcher specific=Pattern.compile("(?:cambia|cambiar|modifica|pone|poner|hace|haz) (?:el )?(?:color (?:del |de |de el |al ))?(?:el )?boton (?:de )?([a-z0-9 ]+?) (?:a |en |de color |color )?(rojo|azul|verde|violeta|amarillo|original)").matcher(q);if(specific.matches())return "pone el boton "+specific.group(1).trim()+" "+specific.group(2);
  Matcher m=Pattern.compile("(?:cambia|cambiar|modifica|pone|poner|haz|hace|haceme) (?:el color de )?(?:los )?botones(?: de (?:la app|banana))? (?:a |en |de color |para que sean )?(azul|azules|verde|verdes|violeta|violetas|rojo|rojos|amarillo|amarillos|original)").matcher(q);if(m.matches()){String color=m.group(1).replaceFirst("es$","").replaceFirst("s$","");return "pone los botones de la app "+color;}
  m=Pattern.compile("(?:cambia|pone|poner|cambiar) (?:el )?(?:tema|fondo)(?: de (?:la app|banana|el chat|chat))? (?:a |en |de color )?(oscuro|azul|verde|violeta)").matcher(q);if(m.matches())return "pone el tema de la app "+m.group(1);
  m=Pattern.compile("(?:hace|haz|haceme|pone) (?:la letra|el texto|los botones)(?: del chat| de la app| de banana)? mas (grande|grandes|chico|chicos|pequeno|pequenos)").matcher(q);if(m.matches())return (m.group(1).startsWith("grande")?"agranda ":"achica ")+(q.contains("botones")?"los botones de la app":"el texto del chat");
  m=Pattern.compile("(?:agranda|achica|aumenta|reduce) (?:la letra|el texto|los botones)(?: del chat| de la app| de banana)?").matcher(q);if(m.matches())return q.substring(0,q.indexOf(' '))+" "+(q.contains("botones")?"los botones de la app":"el texto del chat");
  // Existing canonical adjustments retain their complete validation, including numeric bounds.
  try{AppJavaWorkspace.Settings probe=new AppJavaWorkspace.Settings();if(AppJavaChat.edit(q,probe)!=null)return q;}catch(RuntimeException malformed){throw new IllegalArgumentException("El valor pedido no es válido.");}return null;
 }
 static String payload(String raw){int at=raw.indexOf(':');if(at>=0)return raw.substring(at+1).trim();return raw.replaceFirst("(?iu)^.*?\\bcon\\s+","").trim();}
 static Plan parse(String input,String lastTarget){String raw=polite(input),q=normalize(input);Plan p=new Plan();if(q.matches("que cambiaste|que cambios hiciste|mostrame ese cambio|mostrame el ultimo cambio|como va el cambio"))return new Plan("status","",lastTarget);if(q.matches("(?s)^(?:genera metodo java|cambia el metodo del chat|reescribe el metodo del chat|prepara proyecto java|cambia estas partes de la app|prepara estos cambios|alterna dialogo) .*"))return p;if(q.startsWith("no ")||q.matches("(?s)^(?:como|por que|que pasa|si |cuando .*(?:podrias|podes)).*"))return p;
  if(q.matches("(?:deshace|deshaci|reverti|revierte) (?:ese|el ultimo|este) cambio"))return new Plan("undo","",lastTarget);
  if(q.matches("(?:incorpora|incorporalo|incorporar|guarda|guardalo|integra|integralo|aplica|aplicalo)(?: el cambio| los cambios| esto)? (?:en|a|al) (?:la app|banana|codigo de la app|el codigo de la app|la apk)|(?:reconstruye|reconstrui|reconstruir|genera|generame|prepara|preparame|arma|armame) (?:la |una |mi )?apk(?: normal| actualizada| con los cambios)?"))return new Plan("build","reconstruye mi apk","apk");
  if(q.matches("(?:que cambiaste|que cambios hiciste|mostrame (?:ese|el ultimo) cambio|como va el cambio)"))return new Plan("status","",lastTarget);
  if(q.matches("(?:y )?(?:mas grande|mas chico|mas pequenos|mas grandes)")){if(lastTarget.equals("text")||lastTarget.equals("buttons"))return new Plan("settings",(q.contains("grande")?"agranda ":"achica ")+(lastTarget.equals("text")?"el texto del chat":"los botones de la app"),lastTarget);return new Plan("clarify","","context");}
  if(q.matches("(?:probalo|pruebalo|proba|prueba)(?: con|:).*"))return new Plan("test",payload(raw),"method");
  if(q.matches("(?:ejecutalo|ejecuta el cambio|ejecuta el metodo)(?: con|:).*"))return new Plan("run",payload(raw),"method");
  if(q.matches("(?:arreglalo|reparalo|repara ese metodo|arregla ese metodo)"))return new Plan(lastTarget.equals("method")?"repair":"clarify","","method");
  Matcher reply=Pattern.compile("(?isu)^(?:hace que |haz que |hagas que |cambia el chat para que |cambies el chat para que )?cuando (?:te )?(diga|empiece con|termine con|contenga) ("+JavaTextPlan.LIT+") (?:me )?(?:respondas|responda|responde|digas|diga) ("+JavaTextPlan.LIT+")[.! ]*$").matcher(raw);if(reply.matches()){p=new Plan("reply","","reply");p.detail=reply.group(1).toLowerCase(Locale.ROOT)+" "+reply.group(2)+" responde "+reply.group(3);return p;}
  String[] parts=raw.split("\\s*;\\s*|\\s+y\\s+(?=(?:tambien\\s+)?(?:agranda|achica|aumenta|reduce|cambia|pone|hace|haz|crea|agrega|quita|usa)\\b)",-1);List<String> commands=new ArrayList<>();for(String part:parts){String command=setting(part.replaceFirst("(?iu)^tambien ",""));if(command==null){commands.clear();break;}commands.add(command);}if(!commands.isEmpty()){if(commands.size()>8)throw new IllegalArgumentException("Hasta ocho ajustes por pedido.");String command=JavaCompat.join(";",commands);p=new Plan("settings",command,commands.size()>1?"settings":command.contains("botones")?"buttons":command.contains("texto del chat")?"text":"settings");return p;}
  String task=q.replaceFirst("^(?:el chat|banana|la app) (?=sume|cuente|invierta)","").replaceFirst("^(?:hace|haz|haceme|hagas) que (?:banana|el chat|la app) ","").replaceFirst("^(?:crea|creame|crees|haceme|agrega|agregues|programa|programame|escribi|escribe|genera|generame) (?:un |una )?(?:metodo|funcion|algoritmo)(?: java)? (?:que |para )?","");
  boolean method= !task.equals(q)||q.matches("(?s)^(?:suma|sumar|cuenta|contar|invierte|invertir|recorta) .*(?:lista|arreglo|numeros|texto|cadena|palabra).*" );
  if(method){task=task.replaceAll("\\b(?:sume|sumar)\\b","suma").replaceAll("\\b(?:cuente|contar)\\b","cuenta").replaceAll("\\b(?:invierta|invertir)\\b","invierte");MethodProgram.request(task);return new Plan("method",task,"method");}
  if(q.matches("(?s)^(?:arregla|arreglar|arregles|corrige|corregi|soluciona|repara|cambia|cambiar|cambies|modifica|modificar|modifiques|agrega|agregues|reescribe|mejora|mejores) .*(?:app|codigo|chatbot|botones|texto del chat|tema|boton|segundo personaje|no aparece|no funciona|crashea|error).*"))return new Plan("diagnose",q,"diagnostic");
  return p;
 }
 static void save(Context c,Plan p,String text)throws Exception{prefs(c).edit().putString("target",p.target).putString("kind",p.kind).putString("receipt",text.substring(0,Math.min(text.length(),5000))).putInt("moduleRevision",AppJavaWorkspace.prefs(c).getInt("revision",0)).putInt("replyRevision",JavaMethodEditor.prefs(c).getInt("revision",0)).putString("methodHash",p.kind.equals("method")?JavaMethodEditor.hash(JavaProject.source(c,"JavaAlgorithm.java")):"").commit();}
 static void project(Context c)throws Exception{String base=JavaProject.prefs(c).getString("base","");if(!base.isEmpty()&&!base.equals(JavaProject.fingerprint(c)))JavaProject.handle(c,"actualiza base proyecto java");JavaProject.ensure(c);}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String target=prefs(c).getString("target","");Plan p;try{p=parse(input,target);}catch(IllegalArgumentException bad){return MobileCore.say(c,"No apliqué un cambio parcial: "+bad.getMessage(),"app_ajuste");}if(p.kind.isEmpty())return null;JavaChat.owner=Thread.currentThread();try{
  if(p.kind.equals("clarify"))return MobileCore.say(c,"Necesito que nombres qué querés cambiar: el texto del chat, los botones o el método generado. No modifiqué nada.","app_ajuste");
  if(p.kind.equals("status"))return MobileCore.say(c,prefs(c).getString("receipt","Todavía no registré un cambio pedido de esta forma."),"app_ajuste");
  if(p.kind.equals("build")){project(c);return DurableCode.handle(c,p.command);}
  if(p.kind.equals("diagnose")){String text="Ubicación del problema en las fuentes instaladas:\n"+AndroidRepair.search(c,p.command)+"\nTodavía no puedo producir y comprobar una corrección libre para este pedido. No cambié el código ni la escena. Podés concretar un ajuste de interfaz, una respuesta o un método de listas, texto o turnos.";return MobileCore.say(c,text,"app_ajuste");}
  if(p.kind.equals("undo")){if(target.equals("buttons")||target.equals("text")||target.equals("settings")){if(prefs(c).getInt("moduleRevision",-1)!=AppJavaWorkspace.prefs(c).getInt("revision",0))throw new IllegalArgumentException("Los módulos cambiaron por otra vía; revisá las versiones antes de deshacer.");JSONArray history=AppJavaWorkspace.history(c);if(history.length()==0)throw new IllegalArgumentException("No hay un cambio anterior de módulos.");String text=AppJavaWorkspace.recover(c,history.getJSONObject(history.length()-1).getInt("id"));prefs(c).edit().remove("target").putString("receipt",text).commit();return MobileCore.say(c,text,"app_ajuste");}if(target.equals("method")){if(!JavaProject.fingerprint(c).equals(prefs(c).getString("methodBase",""))||!JavaMethodEditor.hash(JavaProject.source(c,"JavaAlgorithm.java")).equals(prefs(c).getString("methodHash","")))throw new IllegalArgumentException("La copia cambió desde ese pedido; revisá las fuentes antes de deshacer.");String before=prefs(c).getString("methodBefore","");if(before.isEmpty())throw new IllegalArgumentException("No hay una copia anterior del método.");JavaProject.stage(c,"JavaAlgorithm.java",before);String text="Recuperé la copia anterior de JavaAlgorithm.java. El núcleo instalado se conserva. El candidato previo ya no representa la copia; generá otro antes de probar.";prefs(c).edit().remove("target").putString("receipt",text).commit();return MobileCore.say(c,text,"app_ajuste");}if(target.equals("reply")){if(prefs(c).getInt("replyRevision",-1)!=JavaMethodEditor.prefs(c).getInt("revision",0))throw new IllegalArgumentException("El método cambió por otra vía.");JSONArray history=JavaMethodEditor.history(c);if(history.length()==0)throw new IllegalArgumentException("No hay una respuesta anterior.");String text=JavaMethodEditor.recover(c,history.getJSONObject(history.length()-1).getInt("revision"));prefs(c).edit().remove("target").putString("receipt",text).commit();return MobileCore.say(c,text,"app_ajuste");}return MobileCore.say(c,"No tengo una reversión directa de ese cambio. No modifiqué la copia ni el código instalado.","app_ajuste");}
  if(p.kind.equals("test")||p.kind.equals("run")||p.kind.equals("repair")){if(p.kind.equals("repair"))project(c);if(!p.kind.equals("run")&&!MethodLab.prefs(c).contains("candidate"))return MobileCore.say(c,"Primero pedime qué método querés crear; por ejemplo, uno que sume los positivos de una lista.","app_ajuste");return MethodLab.handle(c,p.kind.equals("repair")?"repara mi metodo":(p.kind.equals("test")?"prueba mi metodo: ":"ejecuta mi metodo: ")+p.command);}
  String text;if(p.kind.equals("method")){project(c);String before=JavaProject.source(c,"JavaAlgorithm.java");text=MethodLab.create(c,p.command);prefs(c).edit().putString("methodBefore",before).putString("methodBase",JavaProject.fingerprint(c)).commit();text="Entendí: "+p.command+".\nArchivo: JavaAlgorithm.java · método process.\n"+text.replace("La copia está preparada; probá ‘prueba mi metodo: …’. Para instalarla en el código principal: ‘reconstruye mi apk’ → Banana.apk.","La copia está preparada. Podés decir ‘probalo con: …’ o ‘incorporalo a la app’. El núcleo instalado cambia después de actualizar Banana.apk.");}
  else if(p.kind.equals("settings")){AppJavaWorkspace.restore(c);AppJavaChat.Plan plan=AppJavaChat.plan(p.command,AppJavaWorkspace.live);if(!plan.handled)throw new IllegalArgumentException("No pude preparar el pedido completo.");if(plan.settings.json().toString().equals(AppJavaWorkspace.live.json().toString()))return MobileCore.say(c,"Ese ajuste ya está activo.","app_ajuste");AppJavaWorkspace.prepare(c,plan.settings,plan.summary);text=AppJavaWorkspace.apply(c)+"\nCódigo: BananaInterface.java / BananaAnimation.java / BananaDialogue.java, según el ajuste. Para incorporarlo a la APK podés decir ‘incorporalo a la app’.";}
  else if(p.kind.equals("reply")){Matcher m=Pattern.compile("(?isu)^(diga|empiece con|termine con|contenga) ("+JavaTextPlan.LIT+") responde ("+JavaTextPlan.LIT+")$").matcher(p.detail);if(!m.matches())throw new IllegalArgumentException("No identifiqué la frase y la respuesta completas.");JavaTextPlan plan=JavaMethodEditor.current(c);String op=m.group(1);plan.add(op.equals("diga")?"equals":op.equals("empiece con")?"startsWith":op.equals("termine con")?"endsWith":"contains",JavaTextPlan.decode(m.group(2)),JavaTextPlan.decode(m.group(3)));JavaMethodEditor.prepare(c,plan);text=JavaMethodEditor.apply(c)+"\nArchivo: ChatLanguage.java · socialReply. La respuesta se comprobó en otro proceso y ya está activa.";}
  else return null;save(c,p,text);return MobileCore.say(c,text,"app_ajuste");
 }catch(Exception failure){return MobileCore.say(c,"No completé un cambio nuevo: "+AndroidRepair.summary(failure),"app_ajuste");}finally{JavaChat.owner=null;JavaChat.progress="";}}
}
